module IIC_Driver(
	sys_clk,
	rst_n,
	IICSlave,
	IICWriteReq,
	IICWriteData,
	IICSCL,
	IICWriteDone,
	IICSDA);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [15:0] IICSlave;
	input IICWriteReq;
	input [7:0] IICWriteData;
	output IICSCL;
	output IICWriteDone;
	inout IICSDA;

	wire sys_clk;
	wire rst_n;
	wire [15:0] IICSlave;
	wire IICWriteReq;
	wire [7:0] IICWriteData;
	wire IICSCL;
	wire IICWriteDone;
	wire IICSDA;

	//----Code starts here: integrated by Robei-----
	
	
	    wire      IICReadReq =1'b0;      /*IIC璇诲瘎瀛樺櫒璇锋眰*/
	    wire     IICReadDone;      /*IIC璇诲瘎瀛樺櫒瀹屾垚*/
	    wire[7:0]IICReadData;        /*IIC璇诲彇鏁版嵁*/
	
	
	
	/*IIC 鐘舵??*/
	localparam IIC_IDLE       =   6'b000_001;  /*绌洪棽鎬?*/
	localparam IIC_START      =   6'b000_010;  /*璧峰鎬?*/
	localparam IIC_WRDATA     =   6'b000_100;  /*鍐欐暟鎹??*/
	localparam IIC_RDDATA     =   6'b001_000;  /*璇绘暟鎹??*/
	localparam IIC_ACK        =   6'b010_000;  /*搴旂瓟鎬?*/
	localparam IIC_STOP       =   6'b100_000;  /*鍋滄鎬?*/
	
	
	
	localparam  IIC_Pre       =   3'd4;     /*iiC鍒嗛*/
	    
	reg[5:0]   state , next_state;
	reg[21:0]  IICCnt;              /*IIC璁℃暟鍣?*/
	reg[3:0]   IICBitCnt;           /*IIC鏁版嵁鍙戦?佷釜鏁拌鏁?*/
	reg[1:0]   IICACKStopCnt;       /*IIC ack stop搴旂瓟璁℃暟*/
	reg[2:0]   IICSendBytes;        /*IIC 鍙戦?佸瓧鑺傝鏁?*/ 
	
	
	reg[15:0]   IICSlaveReg;           /*浠庢満鍦板潃+瀵勫瓨鍣ㄦ暟鎹?*/
	reg[7:0]   IICReadDataReg;         /*璇诲彇鍒扮殑鏁版嵁*/
	
	
	reg 	IICWriteReqReg;
	
	reg   iictx;     /*iic鍙戦?佹暟鎹紩鑴?*/
	reg   iicCLK;    /*iic鏃堕挓淇″彿寮曡剼*/
	
	assign IICSDA = (state == IIC_RDDATA || (state == IIC_ACK)) ? 1'bz : iictx;  /*iic涓鸿鏁版嵁鎴栬?呭簲绛旂殑鏃跺?欙紝杈撳嚭涓洪珮闃绘??*/
	assign IICSCL =  iicCLK;
	
	assign IICReadData = IICReadDataReg;
	
	assign IICReadDone  = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	assign IICWriteDone = (state != next_state && state == IIC_STOP) ? 1'b1 : 1'b0;
	
	
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteDone == 1'b1)
			IICWriteReqReg <= 1'b0;
		else if(IICWriteReq == 1'b1)
		   IICWriteReqReg <= 1'b1;
		else
			IICWriteReqReg <= IICWriteReqReg;
	
	end
	
	always @(posedge sys_clk or negedge rst_n) 
	begin
	    if(rst_n == 1'b0)
	        state <= IIC_IDLE;
	    else
	        state <= next_state;   
	end
	
	/*鐘舵?佹満*/
	always @(*)
	begin
	    case(state)
	    IIC_IDLE: 
	        if(IICWriteReq == 1'b1 || IICReadReq == 1'b1)
	            next_state <= IIC_START;
	        else
	            next_state <= IIC_IDLE;
	    IIC_START:
	        if(IICCnt == (IIC_Pre * 'd2))
	            next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_START;
	    IIC_WRDATA:
	        if(IICBitCnt == 'd8 /*&& IICCnt == IIC_Pre /4 */&& iicCLK == 1'b0)
	            next_state <= IIC_ACK;
	        else
	            next_state <= IIC_WRDATA;
	    IIC_RDDATA:
	        if(IICBitCnt == 'd8 && IICCnt == IIC_Pre /4 && iicCLK == 1'b0)
	            next_state <= IIC_ACK;
	        else
	            next_state <= IIC_RDDATA;
	    IIC_ACK:
	        if(IICACKStopCnt == 'd1 /*&& IICCnt == IIC_Pre /4 */&& iicCLK == 1'b0)
	            if(IICSendBytes == 'd2) 
	                if(/*IICWriteReq*/IICWriteReqReg == 1'b1)             /*涓変釜瀛楄妭鍙戦?佸畬鎴愶紝杩涘叆鍋滄鎬?*/
	                    next_state <= IIC_STOP;
	                else 
	                    next_state <= IIC_RDDATA;
	            else if(IICSendBytes == 'd2 && IICReadReq == 1'b1)
	                next_state <= IIC_START;
	            else if(IICSendBytes == 'd4)
	                next_state <= IIC_STOP;
	            else
	                next_state <= IIC_WRDATA;
	        else
	            next_state <= IIC_ACK;
	    IIC_STOP:
	        if(IICACKStopCnt == 'd1 && IICCnt == IIC_Pre/4 && iicCLK == 1'b1)
	            next_state <= IIC_IDLE;
	        else
	            next_state <= IIC_STOP;
	    default:  next_state <= IIC_IDLE;
	    endcase
	end
	
	
	
	/*IIC 鍙戦?佸瓧鑺傝鏁?*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_IDLE)
	        IICSendBytes <= 'd0;
	    else if(state == IIC_ACK)
	        if(next_state != state)
	            IICSendBytes <= IICSendBytes + 1'b1;
	        else
	            IICSendBytes <= IICSendBytes;
	    else
	        IICSendBytes <= IICSendBytes;
	
	end
	
	/*IIC鍒嗛璁℃暟*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICCnt <= 'd0;
	    else if(IICCnt == IIC_Pre && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(IICCnt == (IIC_Pre *'d2) && state != IIC_START)
	        IICCnt <= 'd0;
	    else if(state != next_state)
	        IICCnt <= 'd0;
	    else if(state == IIC_START)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_WRDATA )
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_RDDATA)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_ACK)
	        IICCnt <= IICCnt + 1'b1;
	    else if(state == IIC_STOP)
	        IICCnt <= IICCnt + 1'b1;
	end
	
	/*IIC鍙戦?乥it璁℃暟*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_IDLE || state == IIC_ACK)
	        IICBitCnt <= 'd0;
	    else if(state == IIC_WRDATA && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICBitCnt <= IICBitCnt + 1'b1;
	        else
	            IICBitCnt <= IICBitCnt;
	    else if(state == IIC_RDDATA && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICBitCnt <= IICBitCnt + 1'b1;
	        else
	            IICBitCnt <= IICBitCnt;
	    else
	        IICBitCnt <= IICBitCnt;
	end
	
	
	/*IIC ack stop搴旂瓟璁℃暟*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICACKStopCnt <= 'd0;
	    else if(state != next_state)
	        IICACKStopCnt <= 'd0;
	    else if((state == IIC_ACK || state == IIC_STOP) && IICCnt == (IIC_Pre /2))
	        if(iicCLK == 1'b1)
	            IICACKStopCnt <= IICACKStopCnt + 1'b1;
	        else
	            IICACKStopCnt <= IICACKStopCnt;
	    else if(state == IIC_ACK || state == IIC_STOP)
	        IICACKStopCnt <= IICACKStopCnt;
	    else
	        IICACKStopCnt <= 'd0;
	end
	
	/*IIC浠庢満淇℃伅鎺у埗*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICSlaveReg <= 'd0;
	    else if((IICWriteReq == 1'b1 || IICReadReq == 1'b1) && state == IIC_IDLE)  /*璇锋眰鏉ユ椂锛屼繚瀛樹俊鎭?*/
	        IICSlaveReg <= IICSlave;
	    else if(state == IIC_ACK && state != next_state)   /*姣忓彂閫佸畬鎴愪竴瀛楄妭锛屽氨璋冩崲鏁版嵁锛屽缁堝彂閫佺殑鏄綆8浣?*/
	        if(IICSendBytes == 'd2)
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]} + 1'b1;
	        else
	            IICSlaveReg <= {IICSlaveReg[7:0],IICSlaveReg[15:8]};
	    else
	        IICSlaveReg <= IICSlaveReg;
	end
	
	
	/*IIC 鏃堕挓鎺у埗*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre*2))      /*寮?濮嬬粨鏉熸椂锛屾媺浣庢椂閽熺嚎*/
	        iicCLK <= 1'b0;
	    else if(state == IIC_START && IICCnt > IIC_Pre)
	        iicCLK <= 1'b1;
	    else if(state == IIC_START && IICCnt == IIC_Pre)
	        iicCLK <= iicCLK;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre)     /*鍙戦?佹暟鎹紝渚濇鍙栧弽鏃堕挓绾?*/
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_RDDATA && IICCnt == IIC_Pre)     /*鎺ユ敹鏁版嵁锛屼緷娆″彇鍙嶆椂閽熺嚎*/
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_ACK && IICCnt == IIC_Pre)
	        iicCLK <= ~iicCLK;
	    else if(state == IIC_STOP && IICCnt == IIC_Pre)  /*鍦ㄥ仠姝㈡?佹椂锛孖ICCnt鏃讹紝鐩存帴鎷夐珮iicCLK*/
	        iicCLK <= 1'b1;
	end
	
	
	/*iic 鍙戦?佹帶鍒?*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)   
	        iictx <= 1'b1;
	    else if(state == IIC_START && IICCnt == (IIC_Pre/2))      /*寮?濮嬶紝iic鏁版嵁绾挎媺浣?*/
	        iictx <= 1'b0;
	    else if(state == IIC_START && IICCnt == IIC_Pre/4)      /*寮?濮嬶紝iic鏁版嵁绾挎媺浣?*/
	        iictx <= 1'b1;
	    else if(state == IIC_WRDATA && IICCnt == IIC_Pre / 2)     /*iic鍙戦?佹暟鎹?*/
	        if(iicCLK == 1'b0 && IICSendBytes == 'd2 && (IICWriteReq == 1'b1 || IICWriteReqReg == 1'b1))
	            iictx <= IICWriteData['d7-IICBitCnt];
	        else if(iicCLK == 1'b0)
	            iictx <= IICSlaveReg['d7-IICBitCnt];
	        else
	            iictx <= iictx;
	    else if(state == IIC_ACK)
	        iictx <= 1'b0;
	
	    else if(state == IIC_STOP && IICCnt == (IIC_Pre))
	        if(iicCLK == 1'b1)
	            iictx <= 1'b1;
	        else
	            iictx <= iictx;
	    else if(state == IIC_IDLE)
	        iictx <= 1'b1;
	end
	
	
	/*iic 璇诲彇鏁版嵁鎺у埗*/
	always@(posedge sys_clk or negedge rst_n)
	begin
	    if(rst_n == 1'b0)
	        IICReadDataReg <= 'd0;
	    else if(state == IIC_RDDATA && IICCnt == IIC_Pre / 2)
	        if(iicCLK == 1'b1)
	            IICReadDataReg <= {IICReadDataReg[6:0],IICSDA};
	        else
	            IICReadDataReg <= IICReadDataReg;
	    else
	        IICReadDataReg <= IICReadDataReg;
	end
	
	
	
	
	
	
endmodule    //IIC_Driver

